<?php require_once 'functions.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($pass)<8)$err='Kata sandi minimal 8 karakter.';else{try{$sql=$dbDriver==='pgsql'?"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'user') RETURNING id":"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'user')";$q=$pdo->prepare($sql);$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$userId=$dbDriver==='pgsql'?(int)$q->fetchColumn():(int)$pdo->lastInsertId();$_SESSION['user']=['id'=>$userId,'name'=>$name,'email'=>$email,'role'=>'user'];header('Location: '.app_url('diagnosis.php'));exit;}catch(PDOException $e){$err='Email sudah digunakan atau data tidak valid.';}}} header_html('Daftar');?><section class="auth card"><span class="eyebrow">MULAI DI SINI</span><h1>Buat akun petani</h1><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post" class="form"><label>Nama lengkap<input name="name" required maxlength="100"></label><label>Email<input type="email" name="email" required></label><label>Kata sandi <small>(minimal 8 karakter)</small><input type="password" name="password" minlength="8" required></label><button class="button">Register</button></form><p>Sudah punya akun? <a href="<?=e(app_url('login.php'))?>">Login</a></p></section><?php footer_html();?>
